 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])

    # The repeated row is the horizontal color key; its nonzero entries
    # specify the colors of the vertically stacked copies, top to bottom.
    palette = None
    for r in range(h - 1):
        if grid[r] == grid[r + 1]:
            end = r + 2
            while end < h and grid[end] == grid[r]:
                end += 1
            vals = [v for v in grid[r] if v != 0]
            if len(vals) >= 2:
                palette = vals
                break
    if palette is None:
        raise ValueError('color key not found')

    # Use the largest 4-connected component of color 1 as the motif.
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1}
    components = []
    while cells:
        start = cells.pop()
        comp = {start}
        q = [start]
        while q:
            r, c = q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in cells:
                    cells.remove(p)
                    comp.add(p)
                    q.append(p)
        components.append(comp)
    motif = max(components, key=len)
    r0 = min(r for r, c in motif)
    c0 = min(c for r, c in motif)
    r1 = max(r for r, c in motif)
    c1 = max(c for r, c in motif)
    shape = {(r-r0, c-c0) for r, c in motif}

    output = [[0] * w for _ in range(h)]
    anchor_index = palette.index(1)
    first_top = r0 - anchor_index * (r1-r0+1)
    for i, color in enumerate(palette):
        top = first_top + i * (r1-r0+1)
        for dr, dc in shape:
            rr, cc = top + dr, c0 + dc
            if 0 <= rr < h and 0 <= cc < w:
                output[rr][cc] = color
    return output
